// DecodeMsg implements msgp.Decodable
func (z *Payload) DecodeMsg(dc *msgp.Reader) (err error) {
	var field []byte
	_ = field
	var zb0001 uint32
	zb0001, err = dc.ReadMapHeader()
	if err != nil {
		err = msgp.WrapError(err)
		return
	}
	for zb0001 > 0 {
		zb0001--
		field, err = dc.ReadMapKeyPtr()
		if err != nil {
			err = msgp.WrapError(err)
			return
		}
		switch msgp.UnsafeString(field) {
		case "Total":
			z.Total, err = dc.ReadInt()
			if err != nil {
				err = msgp.WrapError(err, "Total")
				return
			}
		case "Elements":
			var zb0002 uint32
			zb0002, err = dc.ReadArrayHeader()
			if err != nil {
				err = msgp.WrapError(err, "Elements")
				return
			}
			if cap(z.Elements) >= int(zb0002) {
				z.Elements = (z.Elements)[:zb0002]
			} else {
				z.Elements = make([]Book, zb0002)
			}
			for za0001 := range z.Elements {
				err = z.Elements[za0001].DecodeMsg(dc)
				if err != nil {
					err = msgp.WrapError(err, "Elements", za0001)
					return
				}
			}
		default:
			err = dc.Skip()
			if err != nil {
				err = msgp.WrapError(err)
				return
			}
		}
	}
	return
}

// EncodeMsg implements msgp.Encodable
func (z *Payload) EncodeMsg(en *msgp.Writer) (err error) {
	// map header, size 2
	// write "Total"
	err = en.Append(0x82, 0xa5, 0x54, 0x6f, 0x74, 0x61, 0x6c)
	if err != nil {
		return
	}
	err = en.WriteInt(z.Total)
	if err != nil {
		err = msgp.WrapError(err, "Total")
		return
	}
	// write "Elements"
	err = en.Append(0xa8, 0x45, 0x6c, 0x65, 0x6d, 0x65, 0x6e, 0x74, 0x73)
	if err != nil {
		return
	}
	err = en.WriteArrayHeader(uint32(len(z.Elements)))
	if err != nil {
		err = msgp.WrapError(err, "Elements")
		return
	}
	for za0001 := range z.Elements {
		err = z.Elements[za0001].EncodeMsg(en)
		if err != nil {
			err = msgp.WrapError(err, "Elements", za0001)
			return
		}
	}
	return
}

